INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (1, 5, "おいしすぎて食べ始めたら\n止まらない最高のプリンなの\n今のミヤコを止められるヤツは\n誰もいないの", "ペコリーヌのプリン", 100, "プリンセスなプリンなの\nお店にあったいろんな食べもの\nを入れられるだけ入れてみたの\nどんな味なのか楽しみなの", "やばいですね☆なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (2, 5, "なんだかすごくやさしい気持ち\nになる味なの…\nおはようからおやすみまで\nずっと一緒な味なの…", "コッコロのプリン", 101, "いつもオマエのそばに寄りそう\nヤツのぷりんなの。ミヤコの\nワガママもやさしく受け入れて\nくれそうなの", "主さま、なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (3, 5, "いろんな味が一度で楽しめる\nプリンなの。ツンデレはプリン\nにするとおいしいの。ミヤコも\nツンデレを目指してみるの", "キャルのプリン", 102, "ツンツンデレデレなヤツの\nプリンなの。砂糖とスパイスを\n混ぜてみたの。どんな味になる\nか楽しみなの", "ぶっ殺すぞ！なの！\n…デレデレはどこなの？", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (4, 5, "あったかいところで食べる\nプリンアイスは最高なの～♪\n安心しすぎて昔の記憶のない\nミヤコも心が子どもになるの～", "シェフィのプリン", 103, "オマエと同じで、一度赤ちゃん\nみたいになったヤツのプリン\nなの。ヒンヤリ、プリンアイス\nにしてみたの", "おにーたん♪なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (5, 5, "トマトで栄養補給も完璧なの\nどんどん力がみなぎってきて\n復活も夢じゃないの\nミヤコが復活したら…", "イリヤのプリン", 104, "イリヤを見てたら思いついた\nトマトジュースが隠し味の\nプリンなの。栄養満点なの", "ハーハッハッハ！\n世界征服なのじゃなのー！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (6, 5, "見た目がかわいくてもミヤコは\n味にも厳しいの。あむっ…\nこ、これは…！なんだかすごく\n変な気分になってきたの…", "アカリのプリン", 105, "アカリのプリンなの。ヨリと\n同じくらいかわいく作って\nやったの。正直ミヤコは\nおいしければなんでもいいの", "お兄ちゃんのエッチ！　なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (7, 5, "んむぅ…これはなかなか感想が\n難しいプリンなの…率直に言い\nたいような…心のうちに秘めて\nおきたいような…", "ヨリのプリン", 106, "かわいくつくらないとアカリが\n怒りそうだからヨリのプリンは\nかわいく作ったの。自信作なの", "えっと…その…あんたのこと…\nだ、大っ嫌いなのーー！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (8, 5, "このプリンを食べるとシノブが\nミヤコの中にいるみたいなの！\nシノブの力があれば未来の\nプリンを見放題なの！", "シノブのプリン", 107, "シノブはいつもミヤコに\nやさしくしてくれるから\n丁寧に作ったの。ドクロ親父は\nいらないから作ってないの", "お父さん…\nいいかげんにしてなの！\nん？プリンの未来は…\n見えなかったの…", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (9, 5, "固すぎてかじれないから丸吞み\nにしたの。なんだか体が硬く\nなった気がするの。みんなを\n守れる気がするの！", "ジュンのプリン", 108, "黒い鎧を脱がないヤツのプリン\nなの。固めのプリンを目指したら\nカチカチになりすぎたの", "インフェルノシールド！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (10, 5, "口の中でスパイスがプチプチ\nはじけて新食感なの！\nプチプチがミヤコを\n翻弄するの！", "トモのプリン", 109, "オマエをいっつもからかってる\nヤツのプリンなの\nちょっぴり変わったスパイスで\nからかいを表現したの", "あなたといると調子が狂うな\n…なの\n翻弄してたのはオマエなの？", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (11, 5, "ん～見かけによらず濃厚な\nパンチのある味わいが\n口いっぱいに広がるの！", "マツリのプリン", 110, "王宮騎士団にいるちっこいヤツ\nなの。ちっこいけどやるヤツ\nらしいから、濃いめの味付けに\nしてみたの", "タイガーヒーローボンバー！\nなの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (13, 5, "クールな見た目なのにとっても\n優しい味なの！なんだか\n懐かしさを感じるの…", "クロエのプリン", 111, "なんかすごくクールなプリンなの\nなんかテンションも少し\n低そうなの。これ\n食べちゃっても大丈夫なの？", "ま、いいんじゃん？\nしらんけどなの", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (14, 5, "なんか変わった食感なの…\nちゃる…ちょる…ちぇる？\nちぇるってしてるの\nでもちぇるってなんなの？", "チエルのプリン", 112, "きれいにデコれたの！\nカラフルでおいしそうなの\nこれは期待できそうなの", "ぷりーん★なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (15, 5, "味はなんか妙に\n甘酸っぱいの…\n食べたことない味なの\nこの味ってもしかして…", "ユニのプリン", 113, "見た目は完ぺきなの！\nこれをつくったやつは\nきっと天才なの！\n早く食べたいの！", "端的に換言すれば\n青春の味なの？", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (16, 5, "ミヤコも幽霊になる前の記憶\nがないのに、なんだか懐かしい\n気持ちになってくるの…", "サレンのプリン", 114, "オマエから聞いた懐かしい\n味ってヤツを全部入れてみたの\nオマエ記憶がないのに懐かしい\nってどういうことなの？", "幼なじみはあんた…なの？", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (17, 5, "おかしいの。このプリンを\n食べてから、３回も転んだの\nミヤコは幽霊だから転んだり\nしないの。なんでなの…？", "スズメのプリン", 115, "たまたま会ったメイドに教えて\nもらった作り方なの。メイドは\nプリンも作れるはずなの。\nなのにこの不安は何なの…？", "ひゃああんなの～！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (18, 5, "甘さのなかに少しのしょっぱさ\nクセになる味なの\nこのプリンはがんばればきっと\nいろんな美味しいになれるの", "クルミのプリン", 116, "怖がりな子どもが教えてくれた\n小さくてかわいいプリンなの　\n触ってないのにぷるぷる震える\n驚きのやわらかさなの", "サルキデバレヤ！なの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (19, 5, "このプリン、食べるとなんだか\nお姉ちゃんになった気分に\nなるの。ピンチのプリンは\nミヤコが守ってやるの！", "アヤネのプリン", 117, "くまのぬいぐるみを見ていたら\nひらめいたの。小さいけど\nしっかりした甘さの元気に\nなれるプリンなの！", "プリンフルスイングなの～！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (20, 5, "メルヘンパワーがあふれてきて\nいまならミヤコにも魔法が\n使える気がするの！\nほな、いきまひょ～なの！", "マホのプリン", 118, "マホマホ王国って国にいる\nお姫様のプリンなの\n魔物も虜にしちゃう\nすてきなプリンなの", "みらくるみやりん\nくるりんぱ～☆なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (21, 5, "うおーん！ミヤコなんだか\n強くなった気がするの！\n困ったことがあればミヤコが\nまとめて面倒見てやるの！", "マコトのプリン", 119, "カッコいいプリンを目指して\nワイルドなものをガンガン\n入れてみたの。きっと熱い\nプリンができるはずなの", "ウルフェンバイトなの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (22, 5, "一口食べたら元気が\nあふれて止まらないの！\n気分がいいから、一曲\n踊りでも披露してやるの！", "カオリのプリン", 120, "どっかの国でよくとれる\nゴーヤーに似てるやつを\nいれてみたの！ちょっと\n苦いらしいけど…", "なんくるないさ～！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (23, 5, "むむむ…なるほどなの\n上質な糖分をふんだんに\n使うことで、脳をより活性化\nできるからなの！", "カスミのプリン", 121, "勘の鋭いやつが好きな食べ物を\nたくさん入れてみたの\n難しいこと考えるのにぴったり\nらしいけど、なんでなの？", "ふふん。簡単な推理なの", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (24, 5, "ミルクがとっても濃厚で\nほっぺたが落ちちゃうの～♪\nこのプリンからは牧場の…\n自然の息吹を感じるの！", "マヒルのプリン", 122, "搾りたての牛乳を\nたっぷり使ったプリンなの～\nマヒルに手伝ってもらって\nミヤコ直々に搾ってきたの！", "エリザベス～！なの～！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (25, 5, "ほのかな甘さでありながら\nしっかりとした主張も\n感じさせる\n味わい深いプリンなの", "シオリのプリン", 123, "マヒルからやさしいヤツだって\n聞いたの。やさしさを表現\nするために奥ゆかしい甘さに\n仕上げてみたの", "私の好きな本…読んで\nもらえたらうれしいです…\nなの", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (26, 5, "こ、これは…！口の中に入れた\n瞬間にふんわり溶けて\nなくなっちゃうの！\nその食感がやみつきなの！", "リマのプリン", 124, "牧場にいるヤツらしいの\n牛とは違うらしいの\nもふもふ気持ちいいらしいから\n食感にこだわって作ったの", "もふもふにしてあげるなの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (27, 5, "んむぅ…評価が難しい味なの…\nおいしいのはおいしいの…\nん～考えてたら…\n眠くなってきたの…", "リンのプリン", 125, "いっつも寝てるやつらしいの\nぐっすり眠れる薬草をたくさん\n入れてみたの。プリンとして\nおいしくなるかはわからないの", "めんどくさいな～なの…", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (28, 5, "プ…プリンなのにクレープの味\nがするの。味もすごく普通なの\nでも…なんだかプリンの新しい\n扉を開けそうな気がするの…！", "ラビリスタのプリン", 126, "クレープ屋の真っ赤な人に\n教わったプリンなの\n作り方を丁寧に教えてくれて\nとっても優しい人だったの！", "プリンの権能を解放するの～！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (29, 5, "とろける食感が絶品なの～♪\n食べるとなんだか幸せな\n気持ちになれるの…これが\n愛情ってやつなの？", "シズルのプリン", 127, "お店に落ちてた謎のレシピの\nプリンなの。レシピの表紙には\n『お姉ちゃんの愛情たっぷり』\nって書いてあったの", "お姉ちゃんパワー全開！なの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (30, 5, "これで妹力？があがるらしいの。\n妹になればお兄ちゃんに\nプリンをたかり放題なの！\n最高なの～！", "リノのプリン", 128, "リノから作り方を教わったの！\nさすがクレープ屋で働いてる\nだけあって美味しそうなの！", "お兄ちゃん、プリンをよこすの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (31, 5, "食べたら元気が湧いてくるの\nだからプリンのレシピのお礼に\nミヤコも人助けを手伝って\nやったの。ミヤコはえらいの！", "ヒヨリのプリン", 129, "プリンのレシピで悩んでたら\n通りすがりのおねーさんが\n一緒に考えてくれたプリンなの\nいいヤツもたまにはいるの～♪", "困った時はお互いさまさま！\nなの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (32, 5, "はっ…思わずお花畑が見えたの\n身も心も包まれるような\nとっても優しい味がするの\nこれは…まさに癒しなの～♪", "ユイのプリン", 130, "ミヤコががんばって作った\nこだわりのプリンなの～\nプリンは癒しなの。だから優しい\n気持ちで丁寧に作ったの", "フラワリングヒールなの～♪", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (33, 5, "確かに完璧なプリンなの\nでも究極のプリンと呼ぶには\nまだまだ修行が必要なの…\nプリン作りは奥が深いの…！", "レイのプリン", 131, "究極のプリンを作るため\nミヤコは厳しい修行をしたの…\nその結果あって完成した\nクールで完璧なプリンなの！", "スラッシュテンペスト！なの。", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (34, 5, "味にも素材にもこだわりが\nあるの。一流は妥協しないの\nもっと豪華に、もっとおいしく\nできるはず…", "アキノのプリン", 132, "豪華で高級な\nお嬢様プリンなの\n中には宝石みたいな\n大きいイチゴを入れるの！", "おーほっほほほ！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (35, 5, "プリンは飲み物とも言うの\nぐいっていってみるの\n…ふわしゅわでとろけるの～！\n体に染みわたるの～", "ユカリのプリン", 133, "外はしっかり、中はふわとろの\nプリンにするの\n泡みたいなしゅわしゅわの\n生クリームも入れるの♪", "プリしゅわ最高～！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (36, 5, "このプリンは焼きたてのうちに\n食べるのが一番なの…！\n熱いけどおいしくて\nうずうずしてきたの…！", "タマキのプリン", 134, "餡子を入れて\nオーブンでこんがり焼くの\nたい…焼きプリンなの\n斬新なの！", "にゃにゃにゃ！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (37, 5, "プリンはいつでも手軽に\n食べられるのも魅力なの\nこれは食べ応えもあるから一つ\n食べればいっぱい動けるの", "ミフユのプリン", 135, "栄養バランスを考えて\n木の実をたくさん入れるの\nあれこれ忙しいときでも\n頼りになるプリンなの！", "効率全開！なの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (38, 5, "このプリンを食べてから\nいい子になった気がするの\n大好きなプリンを泣いてる子に\nあげたの。いい気分なの", "ミサトのプリン", 136, "エルフの森で子どもにもらった\n薬草を使って作ったの\nこんな優しい味のプリンは\n初めてなの…", "あらあら～なの～♪", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (39, 5, "あまいプリンが口の中で\nぽんぽん弾ける未知の味なの！\n今なら不思議な力で世界も\n救えそうなの！でも眠くなるの…", "ハツネのプリン", 137, "お昼寝でみた夢の中に\nでてきた不思議なプリンを\n作ってみたの。見てたらまた\n眠くなってきたの…", "スヤスヤ～…なの…", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (40, 5, "知らないうちにはしっこに\n隠れちゃってたの。食べたら\nミヤコ、シノブたちに会いに\nいきたくなってきたの", "アオイのプリン", 138, "お店のはしっこに一つだけ\n残ったおもちゃを見て思い\nついたの。他のプリンと一緒に\n置いておくと震えだすの", "ぼっちは卒業なの～！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (41, 5, "口の中に華やかな甘さが\n広がる…これがアイドルなの？\n急に歌って踊りたく\nなってきたの！", "ノゾミのプリン", 139, "トップオブアイドルの\nプリンなの。キラキラした\nものを入れて、あつ～い\nオーブンで焼いてみたの", "リズムあげるのー！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (42, 5, "プリンの生地がとっても\nなめらかで最高の舌触りなの！\n精霊、ミヤコのプリンのために…", "チカのプリン", 140, "ミヤコにプリンをくれるすごく\nいいヤツのプリンなの\n精霊に呼びかけながら\n一生懸命かき混ぜたの", "風の加護を！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (43, 5, "包装は食べるまでの手間が\n増えてめんどくさいの。でも\nそのめんどくささもプリンの\n味を引き立てるの", "ツムギのプリン", 141, "歌って踊って衣装も作れるヤツ\nのプリンなの。このプリンは\nきれいに包装するの。プリンを\n最高の形で着飾らせるの", "騎士さんのために\nしたんじゃありません！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (12, 5, "んむっ！？\nく、口のなかでプリンの\nおいしさが大暴れなの！\n止まらないの！", "クリスティーナのプリン", 142, "プリンをくれないならどうでも\nいいヤツなの。でも横で\nいろいろ言ってきたから\nがんばって作ったの", "宴の始まりなの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (44, 5, "大人の味なの。今やミヤコは\nみんなの頼れる姐御なの！\n悪さするやつはミヤコが\n許さないの！", "ルカのプリン", 143, "大人な甘さ控えめのプリンを\n作るの。試しにお魚を入れて\nみるの。プリンの可能性は\n無限大なの！", "一刀両断、覚悟しな！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (45, 5, "一口食べる度に味が変わって\n魔法みたいなの！\nもしかして全部食べたら\nミヤコも魔法少女になれるの？", "ナナカのプリン", 144, "サイカワサイツヨな\n魔法のプリンなの\n中身をカラフルにするの～\n甘いプリンは頭が冴えるの！", "きゅぴーん！キタコレ！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (46, 5, "一口食べたら謎の組織に\n狙われたり、前世の記憶が蘇る\n気がするの～設定盛りすぎなの\nミヤコは、ミヤコは…", "アンナのプリン", 145, "小難しい言葉をささやきながら\n作ったら魔力あふれるプリンが\n爆誕したの！でも、不思議と\nイタイタしいのはなぜなの～？", "人呼んで、疾風のミヤコなの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (47, 5, "なんか普通のプリンよりも\nいい匂いがするの～…\nプリンのことがもっともっと\n好きになっちゃうの…", "エリコのプリン", 146, "甘酸っぱい赤い木の実を\n切り刻んで入れるの\n甘くてちょっぴり刺激的な\nヤンデレのプリンなの", "クスクス…クスクスクス…なの", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (48, 5, "鼻に抜ける薬のにおいがアレ\nだけど大人っぽくて頭が\nよくなった気がするの。無性に\n実験したくてしかたないの", "ミツキのプリン", 147, "健康に気を遣うミヤコは\nプリンにお薬を入れてみたの～\nでもなんだか毒々しいから\n彩りにバラを添えてみたの～", "どんなプリンも\nミヤコの隻眼からは\n逃れられないの～！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (49, 5, "ん～王道なプリンは\n甘くて安定したおいしさなの～\n思わず笑顔になっちゃうの\nにこにこなの～♪…はっ！", "モニカのプリン", 148, "小さいけどしっかりした\n軍人のプリンなの\nちょっと固めにして\n砂糖はいっぱい入れるの", "私は子どもではない！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (50, 5, "このプリンを食べてから\n誰かにお仕えしなきゃ\nいけない気がするデースなの\nそれはショ、ショー…", "ニノンのプリン", 149, "オーエド町で手に入れた素材と\nトーゴクに伝わる術をかけて\nプリンを作るの。シュババ！\n忍法隠し味の術なの！", "ショーグン！　ミヤコと一緒に\n天下統一するデースなの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (51, 5, "カチカチに固めたせいで食感が\nプリンのようで\nプリンじゃないの…でもこの\nもどかしさが癖になるの…", "クウカのプリン", 150, "オマエが持ってきた手錠を\nヒントに作ったプリンなの\nプリンが動けないように\nカチカチに固めたの", "…ぐふふ、じゅるり～なの", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (52, 5, "味も美しい以外の感想が\n出てこないの。ていうかこれを\n食べたミヤコも美しいの！\n鏡、鏡はどこなの！", "ユキのプリン", 151, "とっても美しいプリンなの\n美しいものを手当たり次第\n入れたらすごいことになったの", "あぁ、ミヤコはなんて美しいの～", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (53, 5, "うん、やっぱりおいしく…\nん？あそこにいるのは\nアイツなの。あれ？\n体が勝手にアイツの方に…", "アユミのプリン", 152, "知らないうちにお菓子が売れた\n時に思いついたプリンなの。\n作り方もよく覚えてない…\nけど、きっとおいしいの！", "ジー…ってミヤコなにしてるの\nミヤコはストーカーじゃないの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (54, 5, "見た目通り甘々で優しい味なの\nでも、レシピを見たら裏面に\n別の作り方が書いてあるの。\nこれだと激辛プリンに…", "ミソギのプリン", 153, "イタズラ好きの手下と一緒に\n作ったプリンなの。見た目は\nかわいいけど、作り方は\n意外と複雑なの～", "にひひ…イタズラの時間なの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (55, 5, "ん～、ふわふわの甘々なの！\nなんだか楽しくなって\n心も体もるんたったしてくるの", "ミミのプリン", 154, "素直でやさしい手下と一緒に\n動物のぬいぐるみをいっぱい\n並べて作ったの", "ぴょんぴょこぴょーん、なの♪", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (56, 5, "ひんやりしてて暑い日でも\nおいしく食べられそうなの！\nん？これを買いたい大人が\nいる？それって…", "キョウカのプリン", 155, "幽霊を怖がっている手下と\n一緒に作ったプリンなの。\n小さいクセにきっちりしてて\nとってもかわいいプリンなの", "へんたいふしんしゃさんなの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (57, 5, "見て食べて楽しめる新機軸の\nプリンなの。ミヤコは幽霊\nだけど自分の足でランウェイを\n歩きたくなってきたの！", "スズナのプリン", 156, "カリスマモデルなプリンなの\nモリモリにデコレーションして\nカリスマ感を演出したの", "ハート狙い撃ち！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (58, 5, "プ、プリンは全部ミヤコのもの\nなのに、なんだかこのプリンは\nいろんな人に教えたく\nなっちゃう不思議な味なの！", "イオのプリン", 157, "学校の先生をしてるヤツの\nプリンなの。お堅くしようと\nしたら、いつの間にか色っぽく\nなっちゃったの。なんでなの？", "授業を始めます♪なの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (59, 5, "ミヤコはプリンならどんなもの\nでも食べるの。でもカラメルを\nちょっとだけ足すの。\nちょっとだけなら…", "ミサキのプリン", 158, "少し背伸びしたおませな子を\n表現したプリンなの。あえて\n甘さ控えめなの。カラメルは\n後乗せできるから安心するの", "立派なレディ、なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (60, 5, "味はすごいゴージャスなの！\nボスの風格があるの！\nビッグなミヤコに\nプリンを捧げるの！", "ホマレのプリン", 159, "謎に包まれたプリンができたの\n何か隠してるようなの…\nこれは危険なプリンなの！", "プリンを持ってこないと\nお仕置きだよ～☆なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (61, 5, "最初の一口目が\nすごいインパクトなの！\n無性にケンカしたくなるの！\nプリンをよこせなの！", "カヤのプリン", 160, "ワイルドな見た目なの！\nこれは期待できそうなの。\nきっと躍動感あふれる味なの！", "たぎってきたの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (62, 5, "見た目はアレだけど味はおいし\nいの…あと主張もはっきりして\nるの！やる気と自信だけは\n出てきたのうおおおーなの！", "イノリのプリン", 161, "なんか見た目がパッとしないの\nこれほんとに大丈夫なの？\nなんか頼りないの…", "下剋上、やってやるですなの！", 0, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (63, 5, "むむむ…食べたら\nやる気が湧いてきたの！\nミヤコを邪魔するやつはみんな\nまとめてぶっ飛ばしてやるの～", "ムイミのプリン", 162, "天下の大悪党のプリンなの\nこれまでのジョーシキに\n捉われないプリンを\n作ってみたの～", "どけどけ～！なの～！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (64, 5, "いつのまにか作ったの全部\n食べちゃったの。なんで\nプリンは分身しないの？\n無限に増えろなの！", "ネネカのプリン", 163, "いろんなものに変身したり\n分身したりできるヤツの\nプリンなの。型で同じプリンを\nたくさんたくさん作ったの", "ミラーミラー！なの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (65, 5, "むぅ…認めたくないけど\nおいしいの…これを何個も\n作れるほどのお金を稼ぐのは\n大変なの…でもおいしいから…", "クレジッタのプリン", 164, "金の亡者のプリンなの\n金にものを言わせて作って\nみたの。おばあちゃんの\nプリンと対極なの", "プリンに忠誠を誓いますわ！\nなの！", 1, 3);
INSERT INTO `v1_3a19b082ddfa380e135a2f46e544c2a008e225b5ccd6d7e98fb6c50dccb87433` VALUES (66, 5, "手堅い…！手堅いの…！\n隙のないプリンなの！\n今のミヤコなら完璧な\n書類作成ができそうなの！", "カリンのプリン", 165, "みんなお世話になるギルド\n管理協会職員のプリンなの\nお役所感を出すために手堅く\n王道に作ったの", "ギルド管理協会へようこそ！\nなの！", 1, 3);
